require_once "auth.php";requireAdmin();require_once "db.php";$id=(int)($_GET["id"]??$_POST["id"]??0);if($id<=0)exit("رقم غير صحيح.");
$s=$conn->prepare("SELECT id,course_name,price,course_image FROM course WHERE id=?");$s->bind_param("i",$id);$s->execute();$course=$s->get_result()->fetch_assoc();if(!$course)exit("الكورس غير موجود.");$message="";
function up($file){if(($file["error"]??4)!==UPLOAD_ERR_OK||($file["size"]??0)>5242880)return false;$f=new finfo(FILEINFO_MIME_TYPE);$m=$f->file($file["tmp_name"]);$a=["image/jpeg"=>"jpg","image/png"=>"png","image/webp"=>"webp","image/gif"=>"gif"];if(!isset($a[$m]))return false;$d=__DIR__."/uploads/courses";if(!is_dir($d))mkdir($d,0755,true);$n=bin2hex(random_bytes(16)).".".$a[$m];return move_uploaded_file($file["tmp_name"],$d."/".$n)?"uploads/courses/".$n:false;}
if($_SERVER["REQUEST_METHOD"]==="POST"){verify_csrf();$name=trim($_POST["course_name"]??"");$price=trim($_POST["price"]??"");if(mb_strlen($name)<2||mb_strlen($name)>150)$message="اسم الكورس يجب أن يكون بين 2 و150 حرفاً.";elseif(!preg_match('/^\d+(?:\.\d{1,2})?$/',$price)||((float)$price<0)||((float)$price>99999999.99))$message="السعر غير صحيح.";else{$new=null;if(($_FILES["course_image"]["error"]??4)!==UPLOAD_ERR_NO_FILE)$new=up($_FILES["course_image"]);if(isset($_FILES["course_image"])&&($_FILES["course_image"]["error"]??4)!==UPLOAD_ERR_NO_FILE&&!$new)$message="الصورة غير صحيحة.";if(!$message){$p=(float)$price;if($new){$u=$conn->prepare("UPDATE course SET course_name=?,price=?,course_image=? WHERE id=?");$u->bind_param("sdsi",$name,$p,$new,$id);}else{$u=$conn->prepare("UPDATE course SET course_name=?,price=? WHERE id=?");$u->bind_param("sdi",$name,$p,$id);}if($u->execute()){if($new&&!empty($course["course_image"]))@unlink(__DIR__."/".$course["course_image"]);header("Location:index.php");exit;}if($new)@unlink(__DIR__."/".$new);$message="حدث خطأ.";}}}
?>
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تعديل كورس</title><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><h1>✏️ تعديل الكورس</h1><?php if($message):?><div class="msg err"><?=htmlspecialchars($message,ENT_QUOTES,"UTF-8")?></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrf_token(),ENT_QUOTES,"UTF-8")?>"><label>اسم الكورس</label><input name="course_name" value="<?=htmlspecialchars($course["course_name"],ENT_QUOTES,"UTF-8")?>" required><label>السعر</label><input type="number" name="price" value="<?=htmlspecialchars($course["price"],ENT_QUOTES,"UTF-8")?>" min="0" step=".01" required><label>صورة جديدة اختيارية</label><input type="file" name="course_image" accept="image/jpeg,image/png,image/webp,image/gif"><br><br><button>حفظ التعديل</button></form></div></div></body></html>